examples.code:
// Three or more of the player's team's Fighting Spirits are out, and
// para_cp0008's is not one of them: dismiss one first
if (CMND_BTL_GET_AVATER_NUM(0) >= 3 && !CMND_BTL_HAS_AVATER("para_cp0008"))
{
	CMND_BTL_RESET_AVATER(0);
}

// Arguments in SET_AVATER order: RESET_AVATER reads "ck0001" as the
// player ID, so this call does nothing (see CMND_BTL_RESET_AVATER)
CMND_BTL_RESET_AVATER("para_cp0008", "ck0001", 0);
